import { useCallback, useEffect, useState } from "react";

export interface User {
  id: string;
  roles: string[];
  [key: string]: any;
}

export interface UseRoleGuardOptions {
  /** The user object. If not provided, attempts to read from session storage. */
  user?: User | null;
  /** URL to redirect to if access is denied. @default "/unauthorized" */
  redirectTo?: string;
  /** Component to render while loading or if unauthorized (not fully implemented in hook logic, mainly for HOCs). */
  fallbackComponent?: React.ComponentType;
  /** Callback fired when access is denied. */
  onUnauthorized?: () => void;
  /** The key used to fetch user data from sessionStorage. @default "user" */
  sessionKey?: string;
}

export interface UseRoleGuardReturn {
  /** Whether the user has the required roles. */
  hasAccess: boolean;
  /** Checks if the user has at least one of the provided roles. */
  hasAnyRole: (roles: string[]) => boolean;
  /** Checks if the user has all of the provided roles. */
  hasAllRoles: (roles: string[]) => boolean;
  /** Whether user data is being loaded. */
  isLoading: boolean;
  /** The current user object. */
  user: User | null;
  /** Manually checks access against a specific set of roles. */
  checkAccess: (requiredRoles: string[]) => boolean;
  /** Function to trigger the redirect manually. */
  redirect: () => void;
}

/**
 * Custom hook for Role-Based Access Control (RBAC).
 * Checks if a user has specific permissions and handles redirection for unauthorized access.
 * @category state
 * @param {string[]} requiredRoles - The list of roles required to access the resource.
 * @param {UseRoleGuardOptions} [options={}] - Configuration options including user object and redirect paths.
 * @returns {UseRoleGuardReturn} Access status, user data, and role checking utilities.
 * @see [Documentation](https://sse-hooks.vercel.app/docs/hooks/use-role-guard)
 * @public
 */
export function useRoleGuard(
  requiredRoles: string[],
  options: UseRoleGuardOptions = {},
): UseRoleGuardReturn {
  const {
    user: providedUser,
    redirectTo = "/unauthorized",
    onUnauthorized,
    sessionKey = "user",
  } = options;

  const [user, setUser] = useState<User | null>(providedUser || null);
  const [isLoading, setIsLoading] = useState(!providedUser);

  useEffect(() => {
    if (!providedUser && typeof window !== "undefined") {
      try {
        const sessionUser = sessionStorage.getItem(sessionKey);
        if (sessionUser) {
          const parsedUser = JSON.parse(sessionUser);
          setUser(parsedUser);
        }
      } catch (error) {
        console.error("Error parsing user from session:", error);
      } finally {
        setIsLoading(false);
      }
    }
  }, [providedUser, sessionKey]);

  const hasAnyRole = useCallback(
    (roles: string[]): boolean => {
      if (!user || !user.roles) return false;
      return roles.some((role) => user.roles.includes(role));
    },
    [user],
  );

  const hasAllRoles = useCallback(
    (roles: string[]): boolean => {
      if (!user || !user.roles) return false;
      return roles.every((role) => user.roles.includes(role));
    },
    [user],
  );

  const checkAccess = useCallback(
    (roles: string[]): boolean => {
      return hasAnyRole(roles);
    },
    [hasAnyRole],
  );

  const hasAccess = checkAccess(requiredRoles);

  const redirect = useCallback(() => {
    if (typeof window !== "undefined" && redirectTo) {
      window.location.href = redirectTo;
    }
  }, [redirectTo]);

  useEffect(() => {
    if (!isLoading && !hasAccess) {
      if (onUnauthorized) {
        onUnauthorized();
      } else if (redirectTo && typeof window !== "undefined") {
        redirect();
      }
    }
  }, [hasAccess, isLoading, onUnauthorized, redirect, redirectTo]);

  return {
    hasAccess,
    hasAnyRole,
    hasAllRoles,
    isLoading,
    user,
    checkAccess,
    redirect,
  };
}

